import com.ezylang.evalex.parser.ParseException;
import com.ezylang.evalex.parser.Token;
import com.ezylang.evalex.parser.Tokenizer;
import com.ezylang.evalex.config.ExpressionConfiguration;
import org.junit.Assert;
import org.junit.Test;

import java.util.List;

public class TokenizerTest {

    @Test
    public void parseValidExpressionTest() throws ParseException {
        final String expression = "1+2";
        final ExpressionConfiguration config = new ExpressionConfiguration();
        final Tokenizer tokenizer = new Tokenizer(expression, config);

        List<Token> tokens = tokenizer.parse();

        Assert.assertNotNull(tokens);
        Assert.assertEquals(3, tokens.size());
    }

    @Test(expected = ParseException.class)
    public void parseInvalidExpressionTest() throws ParseException {
        final String expression = "1#2";
        final ExpressionConfiguration config = new ExpressionConfiguration();
        final Tokenizer tokenizer = new Tokenizer(expression, config);

        tokenizer.parse();
    }

    @Test
    public void parseEmptyExpressionTest() throws ParseException {
        final String expression = "";
        final ExpressionConfiguration config = new ExpressionConfiguration();
        final Tokenizer tokenizer = new Tokenizer(expression, config);

        List<Token> tokens = tokenizer.parse();

        Assert.assertNotNull(tokens);
        Assert.assertTrue(tokens.isEmpty());
    }

    @Test
    public void parseStringLiteralTest() throws ParseException {
        final String expression = "'hello world'";
        final ExpressionConfiguration config = new ExpressionConfiguration();
        final Tokenizer tokenizer = new Tokenizer(expression, config);

        Token token = tokenizer.parseStringLiteral();

        Assert.assertNotNull(token);
        Assert.assertEquals("hello world", token.getSurface());
    }

    @Test(expected = ParseException.class)
    public void parseStringLiteralFaultyTest() throws ParseException {
        final String expression = "'hello world";
        final ExpressionConfiguration config = new ExpressionConfiguration();
        final Tokenizer tokenizer = new Tokenizer(expression, config);

        tokenizer.parseStringLiteral();
    }
}
